def natural_merge_sort(values: list[int]) -> list[int]:
    """Sort a list by iteratively merging ascending runs."""
    if len(values) <= 1:
        return list(values)
    runs: list[list[int]] = []
    start = 0
    for idx in range(1, len(values)):
        if values[idx] < values[idx - 1]:
            runs.append(values[start:idx])
            start = idx
    runs.append(values[start:])
    while len(runs) > 1:
        next_runs: list[list[int]] = []
        for idx in range(0, len(runs), 2):
            if idx + 1 < len(runs):
                next_runs.append(merge_sorted_runs(runs[idx], runs[idx + 1]))
            else:
                next_runs.append(runs[idx])
        runs = next_runs
    return runs[0]

def __init__(self, capacity: int) -> None:
    if capacity <= 0:
        raise ValueError("capacity must be positive")
    self.capacity = capacity
    self._entries: dict[object, object] = {}
    self.hits = 0
    self.misses = 0

def get(self, key: object) -> object | None:
    if key not in self._entries:
        self.misses += 1
        return None
    value = self._entries.pop(key)
    self._entries[key] = value
    self.hits += 1
    return value

def put(self, key: object, value: object) -> object | None:
    evicted = None
    if key in self._entries:
        self._entries.pop(key)
    elif len(self._entries) >= self.capacity:
        oldest = next(iter(self._entries))
        self._entries.pop(oldest)
        evicted = oldest
    self._entries[key] = value
    return evicted

def hit_rate(self) -> float:
    total = self.hits + self.misses
    return self.hits / total if total else 0.0
